public class IRFactoryTest {
    @Test
    public void testEmptyScriptTransformsToScript() throws Exception {
        AstRoot root = new AstRoot();
        Node result = IRFactory.transformTree(root, null, "", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(Token.SCRIPT, result.getType());
        assertFalse(result.hasChildren());
    }

    @Test
    public void testNumberExpressionTransformsToNumberNode() throws Exception {
        AstRoot root = new AstRoot();
        NumberLiteral number = new NumberLiteral();
        number.setNumber(7.0);
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(number);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "7;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        Node expression = result.getFirstChild();
        assertEquals(Token.EXPR_RESULT, expression.getType());
        assertEquals(Token.NUMBER, expression.getFirstChild().getType());
        assertEquals(7.0, expression.getFirstChild().getDouble(), 0.0);
    }

    @Test
    public void testNegativeNumericLiteralFoldsToNegativeNumber() throws Exception {
        AstRoot root = new AstRoot();
        UnaryExpression neg = new UnaryExpression();
        NumberLiteral number = new NumberLiteral();
        number.setNumber(3.0);
        neg.setOperator(com.google.javascript.rhino.head.Token.NEG);
        neg.setOperand(number);
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(neg);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "-3;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(-3.0, result.getFirstChild().getFirstChild().getDouble(), 0.0);
    }

    @Test
    public void testPositiveNumericUnaryExpressionKeepsOperator() throws Exception {
        AstRoot root = new AstRoot();
        UnaryExpression pos = new UnaryExpression();
        NumberLiteral number = new NumberLiteral();
        number.setNumber(3.0);
        pos.setOperator(com.google.javascript.rhino.head.Token.POS);
        pos.setOperand(number);
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(pos);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "+3;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        Node unary = result.getFirstChild().getFirstChild();
        assertEquals(Token.POS, unary.getType());
        assertEquals(3.0, unary.getFirstChild().getDouble(), 0.0);
    }

    @Test
    public void testStringExpressionPreservesValue() throws Exception {
        AstRoot root = new AstRoot();
        StringLiteral literal = new StringLiteral();
        literal.setValue("hi");
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(literal);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "'hi';", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals("hi", result.getFirstChild().getFirstChild().getString());
    }

    @Test
    public void testNameExpressionPreservesIdentifier() throws Exception {
        AstRoot root = new AstRoot();
        Name name = new Name();
        name.setIdentifier("value");
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(name);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "value;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(Token.NAME, result.getFirstChild().getFirstChild().getType());
        assertEquals("value", result.getFirstChild().getFirstChild().getString());
    }

    @Test
    public void testAdditionMapsOperatorAndChildren() throws Exception {
        AstRoot root = new AstRoot();
        InfixExpression add = new InfixExpression();
        NumberLiteral left = new NumberLiteral();
        left.setNumber(2.0);
        NumberLiteral right = new NumberLiteral();
        right.setNumber(4.0);
        add.setOperator(com.google.javascript.rhino.head.Token.ADD);
        add.setLeft(left);
        add.setRight(right);
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(add);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "2+4;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        Node transformed = result.getFirstChild().getFirstChild();
        assertEquals(Token.ADD, transformed.getType());
        assertEquals(2.0, transformed.getFirstChild().getDouble(), 0.0);
        assertEquals(4.0, transformed.getLastChild().getDouble(), 0.0);
    }

    @Test
    public void testParenthesizedExpressionTransformsItsInnerExpression() throws Exception {
        AstRoot root = new AstRoot();
        ParenthesizedExpression parens = new ParenthesizedExpression();
        NumberLiteral number = new NumberLiteral();
        number.setNumber(9.0);
        parens.setExpression(number);
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(parens);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "(9);", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(Token.NUMBER, result.getFirstChild().getFirstChild().getType());
        assertEquals(9.0, result.getFirstChild().getFirstChild().getDouble(), 0.0);
    }

    @Test
    public void testEmptyStatementBecomesEmptyToken() throws Exception {
        AstRoot root = new AstRoot();
        root.addChild(new EmptyStatement());
        Node result = IRFactory.transformTree(root, null, ";", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(Token.EMPTY, result.getFirstChild().getType());
    }

    @Test
    public void testReturnWithValueHasOneExpressionChild() throws Exception {
        AstRoot root = new AstRoot();
        ReturnStatement ret = new ReturnStatement();
        NumberLiteral number = new NumberLiteral();
        number.setNumber(5.0);
        ret.setReturnValue(number);
        root.addChild(ret);
        Node result = IRFactory.transformTree(root, null, "return 5;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        Node transformed = result.getFirstChild();
        assertEquals(Token.RETURN, transformed.getType());
        assertEquals(5.0, transformed.getFirstChild().getDouble(), 0.0);
        assertFalse(transformed.getFirstChild().hasChildren());
    }

    @Test
    public void testReturnWithoutValueHasNoChildren() throws Exception {
        AstRoot root = new AstRoot();
        root.addChild(new ReturnStatement());
        Node result = IRFactory.transformTree(root, null, "return;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(Token.RETURN, result.getFirstChild().getType());
        assertFalse(result.getFirstChild().hasChildren());
    }

    @Test
    public void testArrayLiteralPreservesElementOrder() throws Exception {
        AstRoot root = new AstRoot();
        ArrayLiteral array = new ArrayLiteral();
        NumberLiteral first = new NumberLiteral();
        first.setNumber(1.0);
        NumberLiteral second = new NumberLiteral();
        second.setNumber(2.0);
        array.addElement(first);
        array.addElement(second);
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(array);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "[1,2];", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        Node transformed = result.getFirstChild().getFirstChild();
        assertEquals(Token.ARRAYLIT, transformed.getType());
        assertEquals(1.0, transformed.getFirstChild().getDouble(), 0.0);
        assertEquals(2.0, transformed.getLastChild().getDouble(), 0.0);
    }

    @Test
    public void testAllowedUseStrictDirectiveIsRemovedAndRecorded() throws Exception {
        AstRoot root = new AstRoot();
        ExpressionStatement directive = new ExpressionStatement();
        StringLiteral strict = new StringLiteral();
        strict.setValue("use strict");
        directive.setExpression(strict);
        root.addChild(directive);
        Node result = IRFactory.transformTree(root, null, "'use strict';", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertFalse(result.hasChildren());
        assertEquals(Sets.newHashSet("use strict"), result.getDirectives());
    }

    @Test
    public void testOtherStringExpressionRemainsInScript() throws Exception {
        AstRoot root = new AstRoot();
        ExpressionStatement statement = new ExpressionStatement();
        StringLiteral literal = new StringLiteral();
        literal.setValue("hello");
        statement.setExpression(literal);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "'hello';", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(Token.EXPR_RESULT, result.getFirstChild().getType());
        assertEquals("hello", result.getFirstChild().getFirstChild().getString());
    }

    @Test
    public void testBooleanTrueLiteralMapsToTrueToken() throws Exception {
        AstRoot root = new AstRoot();
        KeywordLiteral literal = new KeywordLiteral();
        literal.setType(com.google.javascript.rhino.head.Token.TRUE);
        ExpressionStatement statement = new ExpressionStatement();
        statement.setExpression(literal);
        root.addChild(statement);
        Node result = IRFactory.transformTree(root, null, "true;", new Config(null, null, false, LanguageMode.ECMASCRIPT5, false), null);
        assertEquals(Token.TRUE, result.getFirstChild().getFirstChild().getType());
    }
